export type ScriptLine = {
    /**
     * Endseconds
     */
    endSeconds: number;
    /**
     * Startseconds
     *
     * From the shot's start.
     */
    startSeconds: number;
    /**
     * Text
     *
     * What to say, word for word.
     */
    text: string;
};

/**
 * Shot
 */
export type Shot = {
    /**
     * Camera
     */
    camera: 'front' | 'back';
    /**
     * Durationseconds
     *
     * How long it lasts in the edit (a photo: how long it is shown).
     */
    durationSeconds: number;
    framing: Framing;
    kind: ShotKind;
    /**
     * on-camera: the viewer films it; voice-over: only their voice is used; asset: nothing is filmed, an asset takes its place.
     */
    mode?: ShotMode;
    phoneAngle: PhoneAngle;
    pose: TargetPose;
    /**
     * Purpose
     *
     * The scene's role in the story (hook, setup, reveal or payoff) and the feeling it's going for.
     */
    purpose: string;
    /**
     * Scene
     *
     * Where to be: "Stand near a tree".
     */
    scene: string;
    /**
     * Scenelandmark
     *
     * The one thing the scene needs, to look for in the camera.
     */
    sceneLandmark: string | null;
    /**
     * Script
     *
     * Empty when nothing is said.
     */
    script: Array<ScriptLine>;
    /**
     * Sourceendseconds
     */
    sourceEndSeconds: number;
    /**
     * Sourcestartseconds
     */
    sourceStartSeconds: number;
    /**
     * Steps
     */
    steps: Array<ShotStep>;
    /**
     * Title
     */
    title: string;
};

export type ShotKind = 'video' | 'photo';

export type ShotMode = 'on-camera' | 'voice-over' | 'asset';

/**
 * ShotPlan
 */
export type ShotPlan = {
    /**
     * Assets
     */
    assets?: Array<Asset>;
    /**
     * Audio
     */
    audio: 'speech' | 'music' | 'speech-and-music' | 'none';
    /**
     * Brands
     */
    brands?: Array<string>;
    /**
     * Durationseconds
     */
    durationSeconds: number;
    /**
     * Edits
     */
    edits?: Array<Edit>;
    /**
     * Format
     *
     * The trend, e.g. "GRWM".
     */
    format: string;
    /**
     * Shots
     */
    shots: Array<Shot>;
    /**
     * Summary
     */
    summary: string;
    /**
     * Title
     */
    title: string;
};

/**
 * ShotStep
 */
export type ShotStep = {
    /**
     * Atseconds
     *
     * From the shot's start.
     */
    atSeconds: number;
    cameraMove: CameraMove;
    /**
     * Instruction
     *
     * One imperative sentence, read out loud.
     */
    instruction: string;
};

/**
 * SpeechRequest
 */
export type SpeechRequest = {
    /**
     * Text
     *
     * The line to say.
     */
    text: string;
    voice: SpeechVoice;
};

export type SpeechVoice = 'Puck' | 'Kore' | 'Aoede' | 'Charon' | 'Sulafat';

/**
 * SpeedEdit
 */
export type SpeedEdit = {
    /**
     * Easing
     */
    easing: 'linear' | 'ease-in' | 'ease-out' | 'ease-in-out';
    /**
     * Endseconds
     */
    endSeconds: number;
    /**
     * Fromrate
     */
    fromRate: number;
    /**
     * Startseconds
     */
    startSeconds: number;
    /**
     * Torate
     */
    toRate: number;
    /**
     * Type
     */
    type: 'speed';
};

/**
 * StockCredit
 *
 * Who made a stock picture and where it's from: shown in the picker and credited in
 * the YouTube description.
 */
export type StockCredit = {
    /**
     * Author
     */
    author: string;
    /**
     * Authorurl
     */
    authorUrl: string;
    /**
     * Pageurl
     */
    pageUrl: string;
    /**
     * Provider
     */
    provider: 'pexels' | 'pixabay';
};

/**
 * TargetPose
 */
export type TargetPose = {
    /**
     * Description
     */
    description: string;
    /**
     * Keypoints
     *
     * The person's joints at the shot's key moment; empty when no one is in it.
     */
    keypoints: Array<Keypoint>;
};

/**
 * TextEdit
 *
 * Words on screen. Captions carry no text of their own: they're the member's words.
 */
export type TextEdit = {
    /**
     * Captionstyle
     */
    captionStyle: 'word-by-word' | 'line' | 'boxed' | null;
    /**
     * Color
     */
    color: string | null;
    /**
     * Endseconds
     */
    endSeconds: number;
    /**
     * Highlightcolor
     */
    highlightColor: string | null;
    /**
     * Position
     */
    position: 'top' | 'middle' | 'bottom' | 'between-halves';
    /**
     * Startseconds
     */
    startSeconds: number;
    /**
     * Style
     */
    style: 'title' | 'lower-third' | 'captions' | 'label' | 'callout';
    /**
     * Text
     */
    text: string | null;
    /**
     * Type
     */
    type: 'text';
};

/**
 * TransitionEdit
 *
 * Into whatever starts at `startSeconds`, lasting until `endSeconds`.
 */
export type TransitionEdit = {
    /**
     * Anchor
     *
     * A match cut's anchor: what lines up.
     */
    anchor: string | null;
    /**
     * Endseconds
     */
    endSeconds: number;
    /**
     * Startseconds
     */
    startSeconds: number;
    /**
     * Transition
     */
    transition: 'cut' | 'match-cut' | 'whip' | 'fade' | 'zoom' | 'spin' | 'glitch';
    /**
     * Type
     */
    type: 'transition';
};

